export class Order {
  constructor(
    readonly id: string,
    private items: readonly OrderItem[],
    private status: 'PENDING' | 'PAID' = 'PENDING'
  ) {}

  calculateTotal(): Money {
    return this.items.reduce((sum, item) => sum.add(item.price), Money.zero());
  }
}

export class CreateOrderUseCase {
  constructor(private readonly orderRepo: OrderRepositoryPort) {}

  async execute(dto: CreateOrderDTO): Promise<OrderResult> {
    const order = new Order(dto.id, dto.items);
    await this.orderRepo.save(order);
    return { success: true, orderId: order.id };
  }
}

export class PostgresOrderAdapter implements OrderRepositoryPort {
  constructor(private pool: PgPool) {}

  async save(order: Order): Promise<void> {
    await this.pool.query('INSERT INTO orders VALUES ($1, $2)', [order.id, order.status]);
  }
}
